___CSS_LOADER_EXPORT___.push([module.id, `/* Portfolio benchmark (Compare) — aligned with dashboard / widget tokens */

.compare-page {
    padding-bottom: 48px;
}

.compare-hero {
    margin: 0 0 28px;
    padding: 22px 24px;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: linear-gradient(165deg, rgba(58, 58, 58, 0.92) 0%, rgba(34, 34, 34, 0.98) 100%);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.22);
}

.compare-hero__title {
    margin: 0 0 10px;
    font-size: clamp(1.35rem, 2.5vw, 1.75rem);
    font-weight: 600;
    letter-spacing: -0.02em;
    color: rgb(245, 245, 245);
}

.compare-hero__lead {
    margin: 0 0 8px;
    font-size: 0.92rem;
    line-height: 1.55;
    color: rgba(255, 255, 255, 0.55);
    max-width: 62ch;
}

.compare-hero__note {
    margin: 0;
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(192, 159, 83, 0.85);
}

.compare-panel {
    margin-bottom: 32px;
    padding: 22px 24px 24px;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: linear-gradient(180deg, rgba(52, 52, 52, 0.95) 0%, rgba(38, 38, 38, 0.98) 100%);
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.2);
}

.compare-panel__title {
    margin: 0 0 18px;
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.38);
}

.compare-slots {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 14px;
}

.compare-slot {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin: 0;
}

.compare-slot__label {
    font-size: 0.68rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.42);
}

.compare-slot__select {
    width: 100%;
    padding: 12px 14px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(0, 0, 0, 0.25);
    color: rgb(230, 230, 230);
    font-size: 0.88rem;
    cursor: pointer;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.compare-slot__select:hover,
.compare-slot__select:focus {
    border-color: rgba(192, 159, 83, 0.45);
    outline: none;
}

.compare-slot__select:focus {
    box-shadow: 0 0 0 2px rgba(192, 159, 83, 0.2);
}

.compare-chips {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.compare-chips__label {
    font-size: 0.65rem;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.35);
    margin-right: 4px;
}

.compare-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 4px 4px 12px;
    border-radius: 999px;
    font-size: 0.78rem;
    font-weight: 500;
    color: rgba(255, 255, 255, 0.88);
    background: rgba(192, 159, 83, 0.18);
    border: 1px solid rgba(192, 159, 83, 0.35);
    max-width: 100%;
}

.compare-chip__name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.compare-chip__remove {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    margin: 0;
    padding: 0;
    border: none;
    border-radius: 50%;
    font-size: 1.15rem;
    line-height: 1;
    color: rgba(255, 255, 255, 0.65);
    background: rgba(0, 0, 0, 0.2);
    cursor: pointer;
    transition:
        background 0.15s ease,
        color 0.15s ease;
}

.compare-chip__remove:hover {
    color: rgb(255, 255, 255);
    background: rgba(180, 70, 65, 0.55);
}

.compare-chip__remove:focus-visible {
    outline: 2px solid rgba(192, 159, 83, 0.85);
    outline-offset: 2px;
}

.compare-actions {
    margin-top: 20px;
}

.compare-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 12px 22px;
    border-radius: 10px;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background 0.2s ease, border-color 0.2s ease, opacity 0.2s ease;
}

.compare-btn--with-icon {
    gap: 10px;
}

.compare-btn__icon {
    flex-shrink: 0;
    display: block;
    opacity: 0.92;
}

.compare-btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.compare-btn--primary {
    color: rgb(34, 34, 34);
    background: linear-gradient(180deg, rgb(218, 190, 120) 0%, rgb(192, 159, 83) 100%);
    border-color: rgba(255, 255, 255, 0.12);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25);
}

.compare-btn--primary:hover:not(:disabled) {
    filter: brightness(1.06);
}

.compare-btn--secondary {
    color: rgba(255, 255, 255, 0.92);
    background: rgba(255, 255, 255, 0.08);
    border-color: rgba(255, 255, 255, 0.14);
}

.compare-btn--secondary:hover:not(:disabled) {
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(192, 159, 83, 0.4);
}

.compare-results__head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 20px;
}

.compare-results__title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 600;
    color: rgb(240, 240, 240);
}

.compare-section-title {
    margin: 28px 0 14px;
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.38);
}

.compare-section-title:first-of-type {
    margin-top: 0;
}

.compare-summary-grid {
    display: grid;
    gap: 16px;
}

.compare-card {
    position: relative;
    overflow: hidden;
    padding: 20px 18px 22px;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: linear-gradient(165deg, rgba(58, 58, 58, 0.92) 0%, rgba(34, 34, 34, 1) 100%);
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.22);
    text-align: left;
}

.compare-card__accent {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        rgba(192, 159, 83, 0.25),
        rgba(218, 190, 120, 0.9),
        rgba(192, 159, 83, 0.25)
    );
}

.compare-card__head {
    margin-bottom: 14px;
}

.compare-card__name {
    margin: 0 0 6px;
    font-size: 1.05rem;
    font-weight: 600;
    color: rgb(245, 245, 245);
    word-break: break-word;
}

.compare-card__total {
    margin: 0 0 4px;
    font-size: 0.82rem;
    color: rgba(192, 159, 83, 0.9);
    font-variant-numeric: tabular-nums;
}

.compare-card__meta {
    margin: 0;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.42);
}

.compare-card__stats {
    margin: 0;
    display: grid;
    gap: 8px;
}

.compare-stat {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 12px;
    padding: 8px 0;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 0.8rem;
}

.compare-stat:first-of-type {
    border-top: none;
    padding-top: 0;
}

.compare-stat dt {
    margin: 0;
    color: rgba(255, 255, 255, 0.45);
    font-weight: 500;
}

.compare-stat dd {
    margin: 0;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    color: rgba(255, 255, 255, 0.82);
}

.compare-stat dd.compare-stat--strong {
    color: rgba(170, 220, 155, 0.95);
}

.compare-table-wrap {
    overflow-x: auto;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(0, 0, 0, 0.2);
}

.compare-table {
    width: 100%;
    min-width: 720px;
    border-collapse: collapse;
    font-size: 0.82rem;
}

.compare-table th,
.compare-table td {
    padding: 12px 14px;
    text-align: left;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.compare-table th {
    font-size: 0.65rem;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.4);
    background: rgba(0, 0, 0, 0.25);
}

.compare-table tbody tr:hover {
    background: rgba(255, 255, 255, 0.04);
}

.compare-table__domain {
    font-weight: 600;
    color: rgb(240, 240, 240);
    max-width: 200px;
    word-break: break-word;
}

.compare-pill {
    display: inline-block;
    padding: 4px 10px;
    border-radius: 999px;
    font-weight: 600;
    font-size: 0.78rem;
    font-variant-numeric: tabular-nums;
}

.compare-pill--pos {
    color: rgba(180, 230, 170, 0.95);
    background: rgba(90, 140, 80, 0.25);
    border: 1px solid rgba(120, 170, 100, 0.35);
}

.compare-pill--neg {
    color: rgba(255, 190, 180, 0.95);
    background: rgba(160, 70, 65, 0.22);
    border: 1px solid rgba(190, 90, 85, 0.35);
}

.compare-device-grid {
    display: grid;
    gap: 16px;
}

.compare-device-card {
    padding: 18px 16px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(0, 0, 0, 0.22);
}

.compare-device-card__title {
    margin: 0 0 12px;
    font-size: 0.9rem;
    font-weight: 600;
    color: rgb(235, 235, 235);
    word-break: break-word;
}

.compare-device-bar {
    display: flex;
    flex-direction: row;
    height: 12px;
    border-radius: 999px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.06);
}

.compare-device-bar__seg {
    min-width: 0;
    height: 100%;
    transition: width 0.35s ease;
}

.compare-device-bar__seg--mobile {
    background: linear-gradient(90deg, rgba(105, 158, 170, 0.85), rgba(130, 185, 198, 0.75));
}

.compare-device-bar__seg--tablet {
    background: linear-gradient(90deg, rgba(192, 159, 83, 0.75), rgba(218, 190, 120, 0.65));
}

.compare-device-bar__seg--desktop {
    background: linear-gradient(90deg, rgba(120, 120, 145, 0.85), rgba(160, 160, 185, 0.7));
}

.compare-device-legend {
    margin: 12px 0 0;
    padding: 0;
    list-style: none;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.5);
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.compare-device-legend__swatch {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 3px;
    margin-right: 6px;
    vertical-align: middle;
}

.compare-interaction-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 14px;
}

.compare-interaction-card {
    padding: 16px 16px 18px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: linear-gradient(180deg, rgba(48, 48, 48, 0.95) 0%, rgba(32, 32, 32, 0.98) 100%);
}

.compare-interaction-card h4 {
    margin: 0 0 12px;
    font-size: 0.88rem;
    font-weight: 600;
    color: rgb(238, 238, 238);
    word-break: break-word;
}

.compare-interaction-list {
    margin: 0;
    padding: 0;
    list-style: none;
    font-size: 0.8rem;
}

.compare-interaction-list li {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    padding: 8px 0;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    color: rgba(255, 255, 255, 0.45);
}

.compare-interaction-list li:first-child {
    border-top: none;
    padding-top: 0;
}

.compare-interaction-list li span:last-child {
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    color: rgba(255, 255, 255, 0.88);
}

.compare-empty {
    padding: 28px 22px;
    border-radius: 12px;
    border: 1px dashed rgba(255, 255, 255, 0.12);
    background: rgba(0, 0, 0, 0.15);
    text-align: center;
}

.compare-empty p {
    margin: 0;
    font-size: 0.9rem;
    line-height: 1.5;
    color: rgba(255, 255, 255, 0.45);
}

@media screen and (max-width: 768px) {
    .compare-results__head {
        flex-direction: column;
        align-items: stretch;
    }

    .compare-btn {
        width: 100%;
    }
}
