.account-picker__title {
    margin: 0 0 6px;
    font-size: 1.1rem;
    font-weight: 700;
    color: rgba(230,235,245,0.95);
}

.account-picker__sub {
    margin: 0;
    font-size: 0.85rem;
    color: rgba(160,170,190,0.8);
    line-height: 1.5;
}

.account-picker__body {
    flex: 1;
    overflow-y: auto;
    padding: 16px 24px;
}

.account-picker__loading,
.account-picker__empty {
    color: rgba(160,170,190,0.7);
    font-size: 0.875rem;
    margin: 8px 0;
}

.account-picker__error {
    color: rgba(248,113,113,0.9);
    font-size: 0.875rem;
    margin: 8px 0;
}

.account-picker__list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.account-picker__item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    border-radius: 8px;
    border: 1px solid rgba(255,255,255,0.06);
    background: rgba(255,255,255,0.03);
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
}

.account-picker__item:hover {
    background: rgba(255,255,255,0.06);
    border-color: rgba(255,255,255,0.12);
}

.account-picker__item--selected {
    background: rgba(99,179,237,0.1);
    border-color: rgba(99,179,237,0.45);
}

.account-picker__item--dim {
    opacity: 0.55;
}

.account-picker__item-radio {
    flex-shrink: 0;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 2px solid rgba(160,170,190,0.4);
    background: transparent;
    position: relative;
    transition: border-color 0.15s;
}

.account-picker__item--selected .account-picker__item-radio {
    border-color: #63b3ed;
}

.account-picker__item--selected .account-picker__item-radio::after {
    content: "";
    position: absolute;
    inset: 3px;
    border-radius: 50%;
    background: #63b3ed;
}

.account-picker__item-info {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}

.account-picker__item-name {
    font-size: 0.9rem;
    font-weight: 600;
    color: rgba(220,230,245,0.95);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.account-picker__item-id {
    font-size: 0.75rem;
    color: rgba(140,155,180,0.75);
    font-family: monospace;
}

.account-picker__footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 16px 24px 20px;
    border-top: 1px solid rgba(255,255,255,0.06);
}

.account-picker__btn {
    padding: 9px 20px;
    border-radius: 8px;
    font-size: 0.875rem;
    font-weight: 600;
    border: none;
    cursor: pointer;
    transition: opacity 0.15s, background 0.15s;
}

.account-picker__btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.account-picker__btn--cancel {
    background: rgba(255,255,255,0.06);
    color: rgba(180,185,200,0.9);
}

.account-picker__btn--cancel:not(:disabled):hover {
    background: rgba(255,255,255,0.1);
}

.account-picker__btn--confirm {
    background: #3b82f6;
    color: #fff;
}

.account-picker__btn--confirm:not(:disabled):hover {
    background: #2563eb;
}

/* ── Sync button & messages ────────────────────────────────────────────── */
.recon-sync-btn {
    padding: 7px 14px;
    border-radius: 7px;
    background: rgba(59, 130, 246, 0.15);
    border: 1px solid rgba(59, 130, 246, 0.4);
    color: rgba(147, 197, 253, 0.95);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s, border-color 0.15s;
    letter-spacing: 0.01em;
}
.recon-sync-btn:not(:disabled):hover {
    background: rgba(59, 130, 246, 0.28);
    border-color: rgba(59, 130, 246, 0.65);
}
.recon-sync-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}
.recon-sync-msg {
    font-size: 0.8rem;
    color: rgba(134, 239, 172, 0.9);
    margin: 6px 0 0;
    padding: 7px 12px;
    background: rgba(34,197,94,0.08);
    border: 1px solid rgba(34,197,94,0.25);
    border-radius: 6px;
}
.recon-sync-msg--error {
    color: rgba(252,165,165,0.9);
    background: rgba(239,68,68,0.08);
    border-color: rgba(239,68,68,0.25);
}
.recon-sync-msg__link {
    color: inherit;
    opacity: 0.8;
    text-decoration: underline;
}
.recon-sync-hint {
    font-size: 0.78rem;
    color: rgba(140,155,180,0.7);
    margin: 5px 0 0;
}
.recon-sync-hint a {
    color: rgba(100,170,255,0.85);
    text-decoration: none;
}
.recon-sync-hint a:hover { text-decoration: underline; }

/* ── UTM attribution health bar ────────────────────────────────────────── */
.utm-health {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px 14px;
    margin: 8px 0;
    border-radius: 8px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    font-size: 0.8rem;
    flex-wrap: wrap;
}
.utm-health__label {
    color: rgba(160,170,190,0.8);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.05em;
    white-space: nowrap;
    min-width: 110px;
}
.utm-health__track {
    flex: 1;
    min-width: 80px;
    height: 6px;
    border-radius: 3px;
    background: rgba(255,255,255,0.08);
    overflow: hidden;
}
.utm-health__fill {
    height: 100%;
    border-radius: 3px;
    transition: width 0.4s ease;
}
.utm-health--good .utm-health__fill { background: #4ade80; }
.utm-health--warn .utm-health__fill { background: #f59e0b; }
.utm-health--bad  .utm-health__fill { background: #f87171; }
.utm-health__stats {
    color: rgba(200,210,225,0.9);
    white-space: nowrap;
}
.utm-health__stats strong { font-weight: 700; }
.utm-health--good .utm-health__stats strong { color: #86efac; }
.utm-health--warn .utm-health__stats strong { color: #fcd34d; }
.utm-health--bad  .utm-health__stats strong { color: #fca5a5; }
.utm-health__dark {
    color: rgba(160,170,190,0.65);
    font-size: 0.75rem;
}

/* ── Insights panel ─────────────────────────────────────────────────────── */
.recon-insights {
    margin: 0;
    flex: 1;
}
.recon-insights__heading {
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: rgba(160,170,190,0.7);
    margin: 0 0 10px;
}
.recon-insights__list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.recon-insight {
    display: flex;
    gap: 12px;
    padding: 12px 16px;
    border-radius: 10px;
    border-left: 3px solid transparent;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
}
.recon-insight--critical {
    background: rgba(239,68,68,0.07);
    border-color: rgba(239,68,68,0.25);
    border-left-color: #ef4444;
}
.recon-insight--warning {
    background: rgba(245,158,11,0.07);
    border-color: rgba(245,158,11,0.25);
    border-left-color: #f59e0b;
}
.recon-insight--opportunity {
    background: rgba(59,130,246,0.07);
    border-color: rgba(59,130,246,0.22);
    border-left-color: #3b82f6;
}
.recon-insight--good {
    background: rgba(34,197,94,0.06);
    border-color: rgba(34,197,94,0.2);
    border-left-color: #22c55e;
}
.recon-insight__icon {
    font-size: 1rem;
    flex-shrink: 0;
    margin-top: 1px;
    width: 18px;
    text-align: center;
}
.recon-insight--critical .recon-insight__icon { color: #f87171; }
.recon-insight--warning  .recon-insight__icon { color: #fbbf24; }
.recon-insight--opportunity .recon-insight__icon { color: #60a5fa; }
.recon-insight--good     .recon-insight__icon { color: #4ade80; }
.recon-insight__content {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
}
.recon-insight__title {
    font-size: 0.875rem;
    font-weight: 700;
    color: rgba(220,230,245,0.95);
    margin: 0;
    line-height: 1.3;
}
.recon-insight__body {
    font-size: 0.8rem;
    color: rgba(170,180,200,0.85);
    margin: 0;
    line-height: 1.55;
}

/* ── Chart sections ─────────────────────────────────────────────────────── */
.recon-chart-section {
    margin: 0;
    background: rgba(255,255,255,0.028);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 20px 20px 16px;
}

.recon-chart-scroll {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.recon-bar-chart {
    display: block;
    width: 100%;
    max-width: 620px;
    height: auto;
    overflow: visible;
}

.recon-chart-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin-top: 10px;
    font-size: 0.78rem;
    color: rgba(160,175,200,0.75);
    align-items: center;
}

.recon-legend-dot {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    margin-right: 4px;
    vertical-align: middle;
    flex-shrink: 0;
}

/* ═══════════════════════════════════════════════════════════════════════════
   DASHBOARD LAYOUT — page header, KPI row, card grid
   ═══════════════════════════════════════════════════════════════════════════ */

.recon-page {
    padding-bottom: 48px;
}

/* ── Page header ──────────────────────────────────────────────────────────── */
.recon-page-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 24px;
    padding-bottom: 18px;
    border-bottom: 1px solid rgba(255,255,255,0.07);
}
.recon-page-header__left {
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-wrap: wrap;
}
.recon-page-header__title {
    margin: 0;
    font-size: 1.4rem;
    font-weight: 700;
    color: rgba(240,242,248,0.97);
    letter-spacing: -0.01em;
}
.recon-page-header__domain {
    font-size: 0.82rem;
    color: rgba(155,170,200,0.75);
    padding: 3px 10px;
    border-radius: 20px;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
}
.recon-page-header__right {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-wrap: wrap;
}
.recon-page-header__channel {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.8rem;
    color: rgba(160,165,175,0.8);
}

.recon-page-header__channel .marketing-reconciliation__select {
    width: auto;
    min-width: 140px;
}
.recon-page-header__back {
    font-size: 0.82rem;
    color: rgba(130,145,175,0.75);
    text-decoration: none;
    transition: color 0.15s;
}
.recon-page-header__back:hover {
    color: rgba(180,190,215,0.9);
}

/* ── Generic card ─────────────────────────────────────────────────────────── */
.recon-card {
    background: rgba(255,255,255,0.028);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 22px 22px 20px;
}
.recon-controls-card {
    margin-bottom: 20px;
}
.recon-card--insights {
    display: flex;
    flex-direction: column;
}
.recon-card__title {
    margin: 0 0 14px;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: rgba(145,158,185,0.65);
}
.recon-card__empty-hint {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0;
    padding: 24px 16px;
    font-size: 0.85rem;
    color: rgba(140,152,175,0.6);
    text-align: center;
}

/* ── KPI stat cards ───────────────────────────────────────────────────────── */
.recon-kpi-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 20px;
}
@media (max-width: 900px) {
    .recon-kpi-row { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
    .recon-kpi-row { grid-template-columns: 1fr 1fr; }
}

.recon-stat-card {
    background: rgba(255,255,255,0.032);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 12px;
    padding: 16px 18px;
    display: flex;
    flex-direction: column;
    gap: 3px;
}
.recon-stat-card--good {
    border-color: rgba(74,222,128,0.2);
    background: rgba(74,222,128,0.045);
}
.recon-stat-card--warn {
    border-color: rgba(245,158,11,0.2);
    background: rgba(245,158,11,0.045);
}
.recon-stat-card--bad {
    border-color: rgba(248,113,113,0.2);
    background: rgba(248,113,113,0.045);
}
.recon-stat-card--ga4 {
    border-color: rgba(227,116,0,0.25);
    background: rgba(227,116,0,0.055);
}
.recon-stat-card--ga4 .recon-stat-card__value { color: rgba(251,191,36,0.95); }
.recon-stat-card__label {
    font-size: 0.68rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: rgba(145,158,180,0.72);
}
.recon-stat-card__value {
    font-size: 1.8rem;
    font-weight: 700;
    line-height: 1.05;
    color: rgba(232,236,248,0.96);
    letter-spacing: -0.025em;
}
.recon-stat-card--good .recon-stat-card__value { color: rgba(134,239,172,0.95); }
.recon-stat-card--warn .recon-stat-card__value { color: rgba(252,211,77,0.92); }
.recon-stat-card--bad  .recon-stat-card__value { color: rgba(248,113,113,0.9); }
.recon-stat-card__sub {
    font-size: 0.71rem;
    color: rgba(135,148,170,0.6);
    margin-top: 1px;
}

/* ── Dashboard 2-col grid (funnel + insights) ─────────────────────────────── */
.recon-dashboard-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 20px;
    align-items: start;
}
@media (max-width: 820px) {
    .recon-dashboard-grid { grid-template-columns: 1fr; }
}

/* ── Charts 2-col grid ────────────────────────────────────────────────────── */
.recon-charts-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 20px;
}
.recon-charts-grid > .recon-chart-section:only-child {
    grid-column: 1 / -1;
}
@media (max-width: 820px) {
    .recon-charts-grid { grid-template-columns: 1fr; }
}

/* ── Alert settings button ───────────────────────────────────────────────── */
.recon-alerts-settings-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 12px;
    background: rgba(99,102,241,0.12);
    border: 1px solid rgba(99,102,241,0.28);
    border-radius: 8px;
    color: rgba(165,168,255,0.9);
    font-size: 0.78rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
    white-space: nowrap;
    flex-shrink: 0;
}
.recon-alerts-settings-btn:hover {
    background: rgba(99,102,241,0.22);
    border-color: rgba(99,102,241,0.5);
}

/* ── Notification bell ───────────────────────────────────────────────────── */
.notif-bell {
    position: relative;
    display: inline-flex;
    align-items: center;
    flex-shrink: 0;
}
.notif-bell__btn {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.09);
    border-radius: 8px;
    color: rgba(180,190,210,0.75);
    cursor: pointer;
    transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.notif-bell__btn:hover {
    background: rgba(255,255,255,0.09);
    color: rgba(220,225,240,0.95);
    border-color: rgba(255,255,255,0.15);
}
.notif-bell__btn--active {
    color: rgba(252,211,77,0.9);
    border-color: rgba(252,211,77,0.3);
    background: rgba(252,211,77,0.07);
}
.notif-bell__badge {
    position: absolute;
    top: -5px;
    right: -5px;
    min-width: 16px;
    height: 16px;
    padding: 0 3px;
    background: #ef4444;
    border-radius: 9px;
    font-size: 0.6rem;
    font-weight: 700;
    color: #fff;
    line-height: 16px;
    text-align: center;
    pointer-events: none;
}

/* ── Notification dropdown ───────────────────────────────────────────────── */
.notif-dropdown {
    position: absolute;
    top: calc(100% + 8px);
    right: 0;
    width: 320px;
    max-height: 420px;
    background: rgba(18,22,36,0.97);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    box-shadow: 0 12px 40px rgba(0,0,0,0.5);
    display: flex;
    flex-direction: column;
    z-index: 999;
    overflow: hidden;
}
.notif-dropdown__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px 10px;
    border-bottom: 1px solid rgba(255,255,255,0.07);
    flex-shrink: 0;
}
.notif-dropdown__title {
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: rgba(180,190,215,0.7);
}
.notif-dropdown__mark-all {
    font-size: 0.71rem;
    color: rgba(99,102,241,0.9);
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
    text-decoration: underline;
}
.notif-dropdown__list {
    overflow-y: auto;
    flex: 1;
    padding: 6px 0;
}
.notif-dropdown__empty {
    margin: 0;
    padding: 16px;
    font-size: 0.78rem;
    color: rgba(155,165,185,0.65);
    line-height: 1.5;
}

/* ── Notification item ───────────────────────────────────────────────────── */
.notif-item {
    position: relative;
    padding: 10px 16px 10px 14px;
    border-left: 3px solid transparent;
    cursor: pointer;
    transition: background 0.12s;
}
.notif-item:hover { background: rgba(255,255,255,0.04); }
.notif-item--unread { background: rgba(99,102,241,0.05); }
.notif-item__meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 3px;
    gap: 8px;
}
.notif-item__type {
    font-size: 0.67rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.notif-item__time {
    font-size: 0.67rem;
    color: rgba(130,140,165,0.6);
    flex-shrink: 0;
}
.notif-item__title {
    margin: 0;
    font-size: 0.8rem;
    color: rgba(215,220,235,0.88);
    line-height: 1.4;
}
.notif-item__dot {
    position: absolute;
    top: 12px;
    right: 12px;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #6366f1;
}

/* ── Alert settings modal ────────────────────────────────────────────────── */
.alert-settings-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(5,8,20,0.72);
    backdrop-filter: blur(4px);
    z-index: 1200;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    padding: 48px 16px;
    overflow-y: auto;
}
.alert-settings-modal {
    background: rgb(14,18,30);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 18px;
    box-shadow: 0 24px 72px rgba(0,0,0,0.7);
    width: 100%;
    max-width: 560px;
    padding: 28px 28px 32px;
    position: relative;
}
.alert-settings-modal__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 22px;
}
.alert-settings-modal__title {
    margin: 0 0 5px;
    font-size: 1.05rem;
    font-weight: 700;
    color: rgba(232,236,248,0.95);
}
.alert-settings-modal__sub {
    margin: 0;
    font-size: 0.8rem;
    color: rgba(150,160,185,0.75);
    line-height: 1.5;
}
.alert-settings-modal__close {
    flex-shrink: 0;
    width: 30px;
    height: 30px;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.09);
    border-radius: 8px;
    color: rgba(180,190,215,0.7);
    font-size: 1.1rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.12s;
}
.alert-settings-modal__close:hover { background: rgba(255,255,255,0.1); }

/* channels section */
.alert-settings-channels {
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 24px;
}
.alert-settings-channels__title {
    margin: 0 0 12px;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: rgba(140,150,175,0.7);
}
.alert-settings-channels__row {
    display: flex;
    flex-direction: column;
    gap: 12px;
}
.alert-settings-channels__item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
}
.alert-settings-channels__icon {
    font-size: 1rem;
    margin-top: 2px;
    flex-shrink: 0;
}
.alert-settings-channels__info {
    display: flex;
    flex-direction: column;
    gap: 6px;
    flex: 1;
}
.alert-settings-channels__name {
    font-size: 0.82rem;
    font-weight: 600;
    color: rgba(210,218,235,0.88);
}
.alert-settings-channels__status {
    font-size: 0.74rem;
    color: rgba(130,140,165,0.65);
}
.alert-settings-email-input {
    width: 100%;
    padding: 7px 10px;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 8px;
    color: rgba(210,218,235,0.9);
    font-size: 0.82rem;
    outline: none;
    transition: border-color 0.15s;
}
.alert-settings-email-input:focus { border-color: rgba(99,102,241,0.5); }
.alert-settings-push-btn {
    padding: 6px 12px;
    background: rgba(99,102,241,0.12);
    border: 1px solid rgba(99,102,241,0.3);
    border-radius: 8px;
    color: rgba(165,168,255,0.9);
    font-size: 0.77rem;
    font-weight: 600;
    cursor: pointer;
    width: fit-content;
    transition: background 0.15s;
}
.alert-settings-push-btn:hover { background: rgba(99,102,241,0.22); }
.alert-settings-push-btn--active {
    background: rgba(74,222,128,0.1);
    border-color: rgba(74,222,128,0.3);
    color: rgba(134,239,172,0.9);
}

/* alert rules */
.alert-settings-rules__title {
    margin: 0 0 12px;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: rgba(140,150,175,0.7);
}
.alert-settings-rules {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.alert-rule {
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 11px;
    padding: 14px 16px;
    transition: border-color 0.15s, background 0.15s;
}
.alert-rule--enabled {
    border-color: rgba(99,102,241,0.25);
    background: rgba(99,102,241,0.04);
}
.alert-rule__top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}
.alert-rule__toggle {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
}
.alert-rule__toggle input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: #6366f1;
    cursor: pointer;
    flex-shrink: 0;
}
.alert-rule__toggle-label {
    font-size: 0.84rem;
    font-weight: 600;
    color: rgba(210,218,235,0.9);
}
.alert-rule__threshold {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
}
.alert-rule__threshold-input {
    width: 72px;
    padding: 5px 8px;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 7px;
    color: rgba(210,218,235,0.9);
    font-size: 0.82rem;
    text-align: right;
    outline: none;
    transition: border-color 0.15s;
}
.alert-rule__threshold-input:focus { border-color: rgba(99,102,241,0.5); }
.alert-rule__threshold-input:disabled { opacity: 0.4; }
.alert-rule__unit {
    font-size: 0.76rem;
    color: rgba(140,150,175,0.65);
    min-width: 24px;
}
.alert-rule__hint {
    margin: 6px 0 0;
    font-size: 0.74rem;
    color: rgba(130,140,165,0.65);
    line-height: 1.45;
}
.alert-rule__channels {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid rgba(255,255,255,0.06);
}
.alert-rule__channel-toggle {
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 0.77rem;
    color: rgba(175,185,210,0.8);
    cursor: pointer;
}
.alert-rule__channel-toggle input[type="checkbox"] {
    width: 13px;
    height: 13px;
    accent-color: #6366f1;
    flex-shrink: 0;
}
.alert-rule__channel-note {
    font-size: 0.7rem;
    color: rgba(120,130,155,0.6);
    font-style: italic;
}

/* ── Cost by channel table ───────────────────────────────────────────────── */
.cost-by-channel {
    width: 100%;
}
.cost-by-channel__table-wrap {
    overflow-x: auto;
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.07);
}
.cost-by-channel__table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.82rem;
}
.cost-by-channel__table th {
    padding: 9px 14px;
    background: rgba(255,255,255,0.03);
    color: rgba(140,152,178,0.72);
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    text-align: left;
    border-bottom: 1px solid rgba(255,255,255,0.07);
    white-space: nowrap;
}
.cost-by-channel__table th.num,
.cost-by-channel__table td.num {
    text-align: right;
}
.cost-by-channel__table td {
    padding: 10px 14px;
    color: rgba(210,218,235,0.88);
    border-bottom: 1px solid rgba(255,255,255,0.04);
    vertical-align: middle;
    white-space: nowrap;
}
.cost-by-channel__table tbody tr:last-child td {
    border-bottom: none;
}
.cost-by-channel__table tbody tr:hover td {
    background: rgba(255,255,255,0.02);
}
.cost-by-channel__dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    margin-right: 7px;
    vertical-align: middle;
    flex-shrink: 0;
}
.cost-col {
    background: rgba(99,102,241,0.04);
}
.cost-by-channel__good { color: rgba(134,239,172,0.9) !important; }
.cost-by-channel__warn { color: rgba(252,211,77,0.85) !important; }
.cost-by-channel__bad  { color: rgba(248,113,113,0.85) !important; }
.cost-by-channel__avg-row td {
    border-top: 1px solid rgba(255,255,255,0.07);
    background: rgba(255,255,255,0.025);
    color: rgba(175,185,210,0.75);
    font-size: 0.78rem;
}

/* ── Connect prompt (inline, below inputs bar) ───────────────────────────── */
.recon-connect-prompt {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    padding: 10px 0 4px;
}
.recon-connect-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 16px;
    background: linear-gradient(135deg, rgba(99,102,241,0.18) 0%, rgba(139,92,246,0.18) 100%);
    border: 1px solid rgba(99,102,241,0.4);
    border-radius: 9px;
    color: rgba(165,168,255,0.95);
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s, opacity 0.15s;
    white-space: nowrap;
}
.recon-connect-btn::before {
    content: "→";
    font-size: 0.9rem;
}
.recon-connect-btn:hover {
    background: linear-gradient(135deg, rgba(99,102,241,0.28) 0%, rgba(139,92,246,0.28) 100%);
    border-color: rgba(99,102,241,0.65);
}
.recon-connect-btn:disabled { opacity: 0.55; cursor: wait; }
.recon-connect-prompt__hint {
    font-size: 0.75rem;
    color: rgba(130,140,165,0.65);
}

/* ── OAuth result banner ─────────────────────────────────────────────────── */
.oauth-banner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 12px 18px;
    border-radius: 11px;
    margin-bottom: 16px;
    font-size: 0.83rem;
    font-weight: 500;
}
.oauth-banner--success {
    background: rgba(74,222,128,0.1);
    border: 1px solid rgba(74,222,128,0.28);
    color: rgba(134,239,172,0.95);
}
.oauth-banner--error {
    background: rgba(248,113,113,0.09);
    border: 1px solid rgba(248,113,113,0.3);
    color: rgba(252,165,165,0.95);
}
.oauth-banner__msg { flex: 1; }
.oauth-banner__close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.1rem;
    color: inherit;
    opacity: 0.7;
    padding: 0 4px;
    line-height: 1;
}
.oauth-banner__close:hover { opacity: 1; }

/* ── Account picker modal ────────────────────────────────────────────────── */
.acct-picker-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(5,8,20,0.78);
    backdrop-filter: blur(5px);
    z-index: 1300;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
}
.acct-picker-modal {
    background: rgb(14,18,30);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 18px;
    box-shadow: 0 28px 80px rgba(0,0,0,0.75);
    width: 100%;
    max-width: 480px;
    padding: 28px 28px 24px;
    max-height: 80vh;
    display: flex;
    flex-direction: column;
}
.acct-picker-modal__header { margin-bottom: 18px; }
.acct-picker-modal__title {
    margin: 0 0 5px;
    font-size: 1.05rem;
    font-weight: 700;
    color: rgba(232,236,248,0.95);
}
.acct-picker-modal__sub {
    margin: 0;
    font-size: 0.8rem;
    color: rgba(150,160,185,0.75);
}
.acct-picker-modal__loading,
.acct-picker-modal__empty {
    margin: 0 0 16px;
    font-size: 0.82rem;
    color: rgba(150,160,185,0.7);
}
.acct-picker-modal__error {
    margin: 0 0 16px;
    font-size: 0.82rem;
    color: rgba(252,165,165,0.9);
    background: rgba(248,113,113,0.08);
    border: 1px solid rgba(248,113,113,0.2);
    border-radius: 8px;
    padding: 10px 14px;
}
.acct-picker-list {
    list-style: none;
    margin: 0 0 16px;
    padding: 0;
    overflow-y: auto;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.acct-picker-item {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 13px 16px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 11px;
    text-align: left;
    cursor: pointer;
    transition: background 0.13s, border-color 0.13s;
}
.acct-picker-item:hover:not(:disabled) {
    background: rgba(99,102,241,0.1);
    border-color: rgba(99,102,241,0.35);
}
.acct-picker-item:disabled { opacity: 0.5; cursor: wait; }
.acct-picker-item__name {
    font-size: 0.88rem;
    font-weight: 600;
    color: rgba(218,224,240,0.95);
    flex: 1;
}
.acct-picker-item__meta {
    font-size: 0.72rem;
    color: rgba(130,140,165,0.65);
    white-space: nowrap;
}
.acct-picker-item__arrow {
    flex-shrink: 0;
    color: rgba(99,102,241,0.6);
}
.acct-picker-modal__cancel {
    width: 100%;
    padding: 10px;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 9px;
    color: rgba(155,165,190,0.7);
    font-size: 0.82rem;
    cursor: pointer;
    transition: background 0.13s;
    flex-shrink: 0;
}
.acct-picker-modal__cancel:hover { background: rgba(255,255,255,0.08); }

