.pxp-report {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.pxp-report__filters {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}

.pxp-report__filter {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 16px;
    border-radius: 12px;
    border: 1px solid rgba(255,255,255,0.08);
    background: rgba(26,26,30,0.75);
    color: rgba(192,159,83,0.85);
}

.pxp-report__filter-text {
    display: flex;
    flex-direction: column;
    gap: 1px;
}

.pxp-report__filter-value {
    font-size: 0.82rem;
    font-weight: 600;
    color: #ececec;
}

.pxp-report__filter-label {
    font-size: 0.68rem;
    color: rgba(150,150,150,0.65);
}

.pxp-report__card {
    background: rgba(26,26,30,0.75);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.18);
}

.pxp-report__card-head {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
}

.pxp-report__metric-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 26px;
    height: 22px;
    padding: 0 6px;
    border-radius: 6px;
    font-size: 0.7rem;
    font-weight: 700;
    color: #4a3a12;
    background: rgba(192,159,83,0.85);
}

.pxp-report__metric-title {
    margin: 0;
    font-size: 0.95rem;
    font-weight: 700;
    color: #ececec;
}

.pxp-collecting {
    margin-bottom: 16px;
    padding: 14px 16px;
    border-radius: 10px;
    background: rgba(252,165,55,0.06);
    border: 1px solid rgba(252,165,55,0.18);
}

.pxp-collecting__head {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.8rem;
    color: rgba(230,200,150,0.9);
    margin-bottom: 10px;
}
.pxp-collecting__head .sa-icon { color: rgba(252,165,55,0.8); }

.pxp-collecting__track {
    display: flex;
    gap: 3px;
    height: 8px;
    border-radius: 5px;
    overflow: hidden;
}

.pxp-collecting__seg {
    height: 100%;
    border-radius: 3px;
}

.pxp-report__table-scroll {
    overflow-x: auto;
}

.pxp-report__table {
    min-width: 640px;
}

.pxp-report__variant-dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    margin-right: 8px;
}

.pxp-report__baseline-chip,
.pxp-report__collecting-chip {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-left: 8px;
    padding: 2px 7px;
    border-radius: 5px;
    font-size: 0.64rem;
    font-weight: 700;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255,255,255,0.06);
    color: rgba(170,170,170,0.75);
}

.pxp-report__table td .pxp-report__collecting-chip {
    margin-left: 0;
    text-transform: none;
    font-weight: 600;
    letter-spacing: 0;
}

.pxp-report__uplift--pos { color: #86e7a4; font-weight: 600; }
.pxp-report__uplift--neg { color: #f0a3a3; font-weight: 600; }

.pxp-report__prob {
    display: inline-flex;
    padding: 2px 8px;
    border-radius: 999px;
    font-weight: 700;
    font-variant-numeric: tabular-nums;
}
.pxp-report__prob--good    { background: rgba(74,222,128,0.15); color: #86e7a4; }
.pxp-report__prob--bad     { background: rgba(239,68,68,0.15);  color: #f0a3a3; }
.pxp-report__prob--neutral { background: rgba(255,255,255,0.06); color: rgba(200,200,200,0.8); }

.pxp-report__total-row td {
    font-weight: 700;
    color: rgba(220,220,220,0.9);
    border-top: 1px solid rgba(255,255,255,0.1);
    border-bottom: none !important;
}

/* ── Graph tabs + charts ─────────────────────────────────────────────────── */

.pxp-graph-tabs {
    display: flex;
    gap: 18px;
    margin-bottom: 14px;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.pxp-graph-tab {
    appearance: none;
    border: none;
    background: transparent;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 0 2px 10px;
    font-size: 0.8rem;
    font-weight: 600;
    color: rgba(160,160,160,0.7);
    border-bottom: 2px solid transparent;
    cursor: pointer;
}
.pxp-graph-tab .sa-icon { color: inherit; }
.pxp-graph-tab.--active {
    color: #e8d9b5;
    border-bottom-color: rgba(192,159,83,0.85);
}

.pxp-graph {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.pxp-graph-scroll {
    overflow-x: auto;
}

.pxp-graph__svg {
    width: 100%;
    min-width: 560px;
    height: auto;
    display: block;
}

.pxp-graph__legend {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
}

.pxp-graph__legend-item {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.76rem;
    color: rgba(190,190,190,0.85);
}

.pxp-graph__legend-dot {
    width: 9px;
    height: 9px;
    border-radius: 50%;
    flex-shrink: 0;
}

/* ── URL split test panel ──────────────────────────────────────────────────── */
.pxp-url-split-panel {
    padding: 24px;
}

.pxp-url-split-variants {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.pxp-url-split-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 8px;
    padding: 14px 16px;
}

.pxp-url-split-row__meta {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 130px;
    flex-shrink: 0;
}

.pxp-url-split-row__label {
    font-weight: 600;
    font-size: 14px;
    color: rgba(255,255,255,0.9);
}

.pxp-url-split-row__control-note {
    flex: 1;
    font-size: 13px;
    color: rgba(200,200,200,0.7);
    margin: 0;
}

.pxp-url-split-row__control-note code {
    color: rgba(200,200,200,0.9);
    font-family: monospace;
    font-size: 12px;
}

.pxp-url-split-row__input {
    flex: 1;
    margin: 0;
}

/* ── Test type tag in list ─────────────────────────────────────────────────── */
.sa-event-row__tag {
    display: inline-flex;
    align-items: center;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.03em;
    color: rgba(200,200,200,0.7);
    background: rgba(255,255,255,0.07);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 4px;
    padding: 2px 7px;
    text-transform: uppercase;
}

/* ── Create form: test type selector ──────────────────────────────────────── */
.sa-event-form__type-row {
    display: flex;
    gap: 10px;
    margin: 4px 0;
}

.sa-event-form__type-opt {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 3px;
    padding: 10px 14px;
    border-radius: 8px;
    border: 1.5px solid rgba(255,255,255,0.1);
    cursor: pointer;
    font-size: 13px;
    font-weight: 600;
    color: rgba(200,200,200,0.8);
    background: rgba(255,255,255,0.03);
    transition: border-color 0.15s, background 0.15s;
    user-select: none;
}

.sa-event-form__type-opt input[type="radio"] {
    display: none;
}

.sa-event-form__type-opt--active {
    border-color: rgba(192,159,83,0.7);
    background: rgba(192,159,83,0.08);
    color: rgba(255,255,255,0.95);
}

.sa-event-form__type-hint {
    font-size: 11px;
    font-weight: 400;
    color: rgba(180,180,180,0.6);
}

.sa-event-form__type-opt--active .sa-event-form__type-hint {
    color: rgba(180,180,180,0.8);
}
