"kpi2\" \"trend\" \"map\";\n    }\n    .sa-conv-grid--deepdive {\n        grid-template-columns: 1fr;\n        grid-template-areas: \"ttc\" \"channels\" \"funnel\" \"campaigns\";\n    }\n}\n\n.sa-map__mode-toggle {\n    margin-left: auto;\n    display: inline-flex;\n    gap: 2px;\n    padding: 2px;\n    border-radius: 8px;\n    background: rgba(255,255,255,0.04);\n    border: 1px solid rgba(255,255,255,0.07);\n}\n\n.sa-map__mode-toggle button {\n    appearance: none;\n    border: none;\n    background: transparent;\n    color: rgba(160,160,160,0.7);\n    font-size: 0.66rem;\n    font-weight: 700;\n    letter-spacing: 0.04em;\n    text-transform: uppercase;\n    padding: 4px 9px;\n    border-radius: 6px;\n    cursor: pointer;\n}\n\n.sa-map__mode-toggle button.is-active {\n    background: rgba(192,159,83,0.18);\n    color: #e8d9b5;\n}\n\n/* ── Time-to-convert breakdown ──────────────────────────────────────────────── */\n\n.sa-ttc-row {\n    grid-template-columns: 90px 1fr 40px;\n}\n\n.sa-ttc-note {\n    margin: 12px 0 0;\n}\n\n.sa-funnel-note {\n    margin: 12px 0 0;\n}\n\n/* ── Checkout funnel ─────────────────────────────────────────────────────────── */\n\n.sa-funnel-step {\n    margin-top: 4px;\n}\n\n.sa-funnel-step__dropoff {\n    font-size: 0.68rem;\n    font-weight: 600;\n    color: rgba(239,120,120,0.8);\n    padding: 4px 0 4px 4px;\n}\n\n.sa-funnel-step__row {\n    display: grid;\n    grid-template-columns: 130px 1fr 90px;\n    align-items: center;\n    gap: 10px;\n}\n\n.sa-funnel-step__label {\n    font-size: 0.8rem;\n    color: rgba(210,210,210,0.9);\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n}\n\n.sa-funnel-step__track {\n    height: 22px;\n    border-radius: 6px;\n    background: rgba(255,255,255,0.05);\n    overflow: hidden;\n}\n\n.sa-funnel-step__fill {\n    height: 100%;\n    min-width: 3px;\n    border-radius: 6px;\n    background: linear-gradient(90deg, rgba(192,159,83,0.85), rgba(192,159,83,0.55));\n    transition: width 0.3s ease;\n}\n\n.sa-funnel-step__value {\n    font-size: 0.8rem;\n    font-weight: 600;\n    color: rgba(210,210,210,0.85);\n    text-align: right;\n    font-variant-numeric: tabular-nums;\n}\n\n.sa-funnel-step__pct {\n    font-weight: 500;\n    color: rgba(150,150,150,0.65);\n    margin-left: 4px;\n}\n\n/* ── Campaign table (expandable rows) ───────────────────────────────────────── */\n\n.sa-campaign-row {\n    cursor: pointer;\n}\n\n.sa-campaign-row:hover td {\n    background: rgba(255,255,255,0.02);\n}\n\n.sa-campaign-row--flat {\n    cursor: default;\n}\n\n.sa-campaign-row--flat:hover td {\n    background: transparent;\n}\n\n.sa-campaign-row__toggle {\n    width: 20px;\n    padding-right: 0 !important;\n}\n\n.sa-campaign-row__toggle .sa-icon {\n    transition: transform 0.15s ease;\n}\n\n.sa-campaign-row__chevron--open {\n    transform: rotate(-180deg);\n}\n\n.sa-campaign-row__detail td {\n    border-bottom: 1px solid rgba(255,255,255,0.04);\n    padding-top: 0;\n    padding-bottom: 10px;\n}\n\n.sa-campaign-events {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 6px;\n}\n\n.sa-campaign-event-chip {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    font-size: 0.72rem;\n    color: rgba(190,190,190,0.8);\n    background: rgba(255,255,255,0.04);\n    border: 1px solid rgba(255,255,255,0.07);\n    border-radius: 999px;\n    padding: 3px 10px 3px 12px;\n}\n\n.sa-campaign-event-chip b {\n    color: #ececec;\n    font-weight: 700;\n}\n/* ─── GA4 Card (Channel Analytics) ──────────────────────────────────────── */\n.ga4-card {\n    margin: 4px 0 18px;\n    padding: 18px 20px 16px;\n    background: rgba(227,116,0,0.04);\n    border: 1px solid rgba(227,116,0,0.14);\n    border-radius: 14px;\n}\n.ga4-card__header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    margin-bottom: 14px;\n}\n.ga4-card__title {\n    font-size: 0.78rem;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.07em;\n    color: rgba(227,116,0,0.9);\n}\n.ga4-card__badges {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n.ga4-sessions-chart__syncing {\n    font-size: 0.72rem;\n    color: rgba(227,116,0,0.6);\n}\n\n/* GA4 KPI strip */\n.ga4-kpi-strip {\n    display: flex;\n    gap: 0;\n    margin-bottom: 16px;\n    border: 1px solid rgba(227,116,0,0.12);\n    border-radius: 10px;\n    overflow: hidden;\n}\n.ga4-kpi {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    padding: 10px 8px;\n    border-right: 1px solid rgba(227,116,0,0.1);\n    cursor: default;\n    transition: background 0.12s;\n}\n.ga4-kpi:last-child { border-right: none; }\n.ga4-kpi:hover { background: rgba(227,116,0,0.07); }\n.ga4-kpi__value {\n    font-size: 1.25rem;\n    font-weight: 700;\n    color: rgba(240,190,80,0.95);\n    letter-spacing: -0.02em;\n    line-height: 1.1;\n}\n.ga4-kpi__label {\n    font-size: 0.66rem;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n    color: rgba(145,158,180,0.65);\n    margin-top: 2px;\n    white-space: nowrap;\n}\n.ga4-ss-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    padding: 3px 10px;\n    background: rgba(99,102,241,0.12);\n    border: 1px solid rgba(99,102,241,0.3);\n    border-radius: 20px;\n    font-size: 0.71rem;\n    font-weight: 600;\n    color: rgba(165,170,255,0.95);\n    letter-spacing: 0.01em;\n}\n\n/* Platform breakdown */\n.ga4-platform-breakdown {\n    margin-top: 16px;\n    padding-top: 14px;\n    border-top: 1px solid rgba(255,255,255,0.06);\n}\n.ga4-platform-breakdown__title {\n    margin: 0 0 10px;\n    font-size: 0.72rem;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.06em;\n    color: rgba(145,158,180,0.65);\n}\n.ga4-platform-breakdown__rows {\n    display: flex;\n    flex-direction: column;\n    gap: 7px;\n}\n.ga4-pb-row {\n    display: grid;\n    grid-template-columns: 160px 1fr 52px 70px;\n    align-items: center;\n    gap: 10px;\n    font-size: 0.8rem;\n}\n.ga4-pb-row__name {\n    color: rgba(185,195,215,0.85);\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n}\n.ga4-pb-row--ss .ga4-pb-row__name {\n    color: rgba(165,170,255,0.9);\n    font-weight: 600;\n}\n.ga4-pb-row__ss-icon {\n    margin-right: 4px;\n}\n.ga4-pb-row__ss-hint {\n    font-size: 0.7rem;\n    font-weight: 400;\n    color: rgba(140,145,200,0.65);\n    margin-left: 4px;\n}\n.ga4-pb-row__bar-wrap {\n    height: 8px;\n    background: rgba(255,255,255,0.05);\n    border-radius: 4px;\n    overflow: hidden;\n}\n.ga4-pb-row__bar {\n    height: 100%;\n    border-radius: 4px;\n    transition: width 0.3s ease;\n}\n.ga4-pb-row__share {\n    text-align: right;\n    color: rgba(145,160,185,0.75);\n    font-size: 0.75rem;\n}\n.ga4-pb-row__count {\n    text-align: right;\n    color: rgba(185,195,215,0.7);\n    font-size: 0.75rem;\n    font-variant-numeric: tabular-nums;\n}\n\n/* ─── Channel Analytics Redesigned Layout ───────────────────────────────── */\n\n/* Compact page header */\n.ca-page-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 16px;\n    margin-bottom: 16px;\n    flex-wrap: wrap;\n}\n.ca-page-header__left {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    flex-wrap: wrap;\n}\n.ca-page-header__title {\n    margin: 0;\n    font-size: 1.15rem;\n    font-weight: 700;\n    color: rgba(235,240,255,0.96);\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n.ca-page-header__channel {\n    color: rgba(200,210,240,0.9);\n    font-weight: 600;\n}\n.ca-back-btn {\n    background: none;\n    border: none;\n    padding: 0;\n    font-size: 0.82rem;\n    font-weight: 600;\n    color: rgba(145,160,200,0.75);\n    cursor: pointer;\n    white-space: nowrap;\n    transition: color 0.12s;\n}\n.ca-back-btn:hover { color: rgba(200,210,240,0.95); }\n.ca-compare-pill {\n    display: inline-block;\n    padding: 3px 10px;\n    background: rgba(99,102,241,0.12);\n    border: 1px solid rgba(99,102,241,0.22);\n    border-radius: 20px;\n    font-size: 0.71rem;\n    color: rgba(165,170,255,0.85);\n}\n.ca-reconcile-link {\n    display: inline-block;\n    padding: 6px 14px;\n    background: rgba(99,102,241,0.1);\n    border: 1px solid rgba(99,102,241,0.22);\n    border-radius: 8px;\n    font-size: 0.77rem;\n    font-weight: 600;\n    color: rgba(165,170,255,0.88);\n    text-decoration: none;\n    transition: background 0.13s;\n    white-space: nowrap;\n}\n.ca-reconcile-link:hover { background: rgba(99,102,241,0.18); color: rgba(185,190,255,0.95); }\n\n/* Consent KPI strip */\n.ca-kpi-strip {\n    display: flex;\n    gap: 0;\n    margin-bottom: 16px;\n    border: 1px solid rgba(255,255,255,0.07);\n    border-radius: 12px;\n    overflow: hidden;\n}\n.ca-kpi {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    padding: 12px 8px;\n    border-right: 1px solid rgba(255,255,255,0.06);\n    cursor: default;\n    min-width: 0;\n    transition: background 0.12s;\n}\n.ca-kpi:last-child { border-right: none; }\n.ca-kpi:hover { background: rgba(255,255,255,0.035); }\n.ca-kpi__value {\n    font-size: 1.3rem;\n    font-weight: 700;\n    color: rgba(232,236,248,0.95);\n    letter-spacing: -0.025em;\n    line-height: 1.1;\n    white-space: nowrap;\n}\n.ca-kpi--warn .ca-kpi__value { color: rgba(252,165,50,0.92); }\n.ca-kpi__label {\n    font-size: 0.64rem;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n    color: rgba(140,155,180,0.6);\n    margin-top: 3px;\n    text-align: center;\n    line-height: 1.2;\n}\n.ca-kpi__compare {\n    margin-top: 3px;\n    font-size: 0.7rem;\n}\n\n/* Table section header with inline toolbar */\n.ca-table-section { margin-bottom: 0; }\n.ca-table-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    margin-bottom: 10px;\n    flex-wrap: wrap;\n}\n.ca-table-toolbar {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    flex-wrap: wrap;\n}\n\n/* Collapsed context section */\n.ca-context-details {\n    margin: 16px 0 4px;\n}\n.ca-context-summary {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    padding: 10px 14px;\n    background: rgba(255,255,255,0.03);\n    border: 1px solid rgba(255,255,255,0.07);\n    border-radius: 10px;\n    cursor: pointer;\n    font-size: 0.8rem;\n    font-weight: 600;\n    color: rgba(170,180,210,0.8);\n    list-style: none;\n    user-select: none;\n    transition: background 0.12s;\n}\n.ca-context-summary::-webkit-details-marker { display: none; }\n.ca-context-summary::before {\n    content: \"▸\";\n    font-size: 0.7rem;\n    color: rgba(140,155,180,0.5);\n    transition: transform 0.15s;\n}\ndetails[open] .ca-context-summary::before { content: \"▾\"; }\n.ca-context-summary:hover { background: rgba(255,255,255,0.055); }\n.ca-context-summary__hint {\n    font-size: 0.69rem;\n    font-weight: 400;\n    color: rgba(130,145,170,0.55);\n    margin-left: 4px;\n}\n.ca-context-details[open] .ca-context-summary {\n    border-radius: 10px 10px 0 0;\n    border-bottom: none;\n}\n\n/* ─── GA4 Coverage & Blindspots ─────────────────────────────────────────── */\n\n.ga4-coverage {\n    margin: 20px 0 0;\n    padding: 16px 20px;\n    background: rgba(255,255,255,0.025);\n    border-radius: 10px;\n    border: 1px solid rgba(255,255,255,0.07);\n}\n.ga4-coverage__header {\n    display: flex;\n    align-items: baseline;\n    gap: 10px;\n    margin-bottom: 14px;\n}\n.ga4-coverage__title {\n    margin: 0;\n    font-size: 0.75rem;\n    font-weight: 700;\n    letter-spacing: 0.06em;\n    text-transform: uppercase;\n    color: rgba(192,159,83,0.9);\n}\n.ga4-coverage__subtitle {\n    font-size: 0.72rem;\n    color: rgba(140,155,180,0.65);\n}\n.ga4-coverage__metrics {\n    display: flex;\n    gap: 0;\n    flex-wrap: wrap;\n    margin-bottom: 14px;\n    border: 1px solid rgba(255,255,255,0.07);\n    border-radius: 8px;\n    overflow: hidden;\n}\n.ga4-coverage__metric {\n    flex: 1;\n    min-width: 90px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    padding: 10px 12px;\n    border-right: 1px solid rgba(255,255,255,0.07);\n    gap: 3px;\n}\n.ga4-coverage__metric:last-child { border-right: none; }\n.ga4-coverage__metric--dark { background: rgba(239,68,68,0.05); }\n.ga4-coverage__metric-value {\n    font-size: 1.05rem;\n    font-weight: 700;\n    font-variant-numeric: tabular-nums;\n    color: rgba(235,240,255,0.95);\n    letter-spacing: -0.01em;\n}\n.ga4-coverage__metric--dark .ga4-coverage__metric-value {\n    color: rgba(239,68,68,0.85);\n}\n.ga4-coverage__metric-label {\n    font-size: 0.67rem;\n    color: rgba(140,155,180,0.7);\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n}\n/* Stacked bar */\n.ga4-coverage__bar-track {\n    position: relative;\n    height: 10px;\n    background: rgba(239,68,68,0.2);\n    border-radius: 6px;\n    overflow: hidden;\n    margin-bottom: 6px;\n}\n.ga4-coverage__bar-fill {\n    position: absolute;\n    left: 0; top: 0; bottom: 0;\n    background: linear-gradient(90deg, rgba(74,222,128,0.75), rgba(34,197,94,0.65));\n    border-radius: 6px;\n    transition: width 0.4s ease;\n    min-width: 2px;\n}\n.ga4-coverage__bar-legend {\n    display: flex;\n    gap: 16px;\n    margin-bottom: 10px;\n    font-size: 0.7rem;\n}\n.ga4-coverage__legend-consent::before {\n    content: \"■\";\n    color: rgba(74,222,128,0.75);\n    margin-right: 4px;\n}\n.ga4-coverage__legend-dark::before {\n    content: \"■\";\n    color: rgba(239,68,68,0.4);\n    margin-right: 4px;\n}\n.ga4-coverage__legend-consent { color: rgba(165,185,215,0.75); }\n.ga4-coverage__legend-dark    { color: rgba(165,185,215,0.75); }\n.ga4-coverage__note {\n    margin: 0;\n    font-size: 0.71rem;\n    color: rgba(130,145,170,0.6);\n    line-height: 1.5;\n}\n\n/* ─── GA4 Channel Cross-reference ───────────────────────────────────────── */\n\n.ga4-xref {\n    margin: 20px 0 0;\n    padding: 16px 20px 12px;\n    background: rgba(255,255,255,0.02);\n    border-radius: 10px;\n    border: 1px solid rgba(255,255,255,0.07);\n}\n.ga4-xref__header {\n    display: flex;\n    align-items: baseline;\n    gap: 10px;\n    margin-bottom: 12px;\n    flex-wrap: wrap;\n}\n.ga4-xref__title {\n    margin: 0;\n    font-size: 0.75rem;\n    font-weight: 700;\n    letter-spacing: 0.06em;\n    text-transform: uppercase;\n    color: rgba(192,159,83,0.9);\n}\n.ga4-xref__subtitle {\n    font-size: 0.69rem;\n    color: rgba(130,145,170,0.55);\n}\n.ga4-xref__scroll {\n    overflow-x: auto;\n    -webkit-overflow-scrolling: touch;\n    margin-bottom: 10px;\n}\n.ga4-xref__table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 0.78rem;\n}\n.ga4-xref__th {\n    padding: 6px 10px;\n    text-align: left;\n    font-size: 0.68rem;\n    font-weight: 600;\n    letter-spacing: 0.04em;\n    text-transform: uppercase;\n    color: rgba(140,155,180,0.7);\n    border-bottom: 1px solid rgba(255,255,255,0.08);\n    white-space: nowrap;\n}\n.ga4-xref__th--num { text-align: right; }\n.ga4-xref__td {\n    padding: 7px 10px;\n    color: rgba(215,225,245,0.85);\n    border-bottom: 1px solid rgba(255,255,255,0.04);\n    vertical-align: middle;\n}\n.ga4-xref__td--num {\n    text-align: right;\n    font-variant-numeric: tabular-nums;\n}\n.ga4-xref__td--channels {\n    font-size: 0.72rem;\n    color: rgba(180,195,225,0.7);\n    max-width: 220px;\n}\n.ga4-xref__row--blind {\n    background: rgba(239,68,68,0.04);\n}\n.ga4-xref__row--blind .ga4-xref__td { color: rgba(220,230,250,0.85); }\n.ga4-xref__blind-badge {\n    display: inline-block;\n    font-size: 0.6rem;\n    font-weight: 700;\n    letter-spacing: 0.05em;\n    text-transform: uppercase;\n    color: rgba(239,68,68,0.9);\n    background: rgba(239,68,68,0.12);\n    border: 1px solid rgba(239,68,68,