.notif-center {
    position: relative;
    display: flex;
    align-items: center;
}

.notif-bell {
    position: relative;
    background: none;
    border: none;
    cursor: pointer;
    color: rgb(197, 197, 197);
    padding: 6px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.15s, color 0.15s;
}
.notif-bell:hover {
    background: rgba(255,255,255,0.08);
    color: #fff;
}

.notif-badge {
    position: absolute;
    top: 2px;
    right: 2px;
    background: #e05252;
    color: #fff;
    font-size: 0.6rem;
    font-weight: 700;
    min-width: 16px;
    height: 16px;
    border-radius: 8px;
    padding: 0 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    pointer-events: none;
}

.notif-dropdown {
    position: absolute;
    top: calc(100% + 10px);
    right: 0;
    width: 340px;
    background: #2a2a2a;
    border: 1px solid rgba(255,255,255,0.1);
